app.post('/api/pay-use/jotters/purchase',auth,async(req,res)=>{const units=Math.max(1,Math.min(100,Number(req.body.units)||1)),requestId=String(req.body.requestId||'').trim().slice(0,100);if(!requestId)return res.status(400).json({error:'Identificativo richiesta mancante'});const c=await pool.connect();try{await c.query('BEGIN');await c.query('SELECT pg_advisory_xact_lock(hashtext($1))',[req.user.sub+':jotter-extra']);const dup=await c.query("SELECT id FROM pay_use_transactions WHERE provider='internal-jotters' AND external_id=$1",[requestId]);if(dup.rowCount){await c.query('ROLLBACK');return res.status(409).json({error:'Richiesta già elaborata'})}const settings=(await c.query('SELECT * FROM pay_use_settings WHERE id=1')).rows[0],u=(await c.query('SELECT spot_credit_cents FROM users WHERE id=$1 FOR UPDATE',[req.user.sub])).rows[0],unit=Number(settings.jotter_cost_cents||0),total=unit*units,balance=Number(u?.spot_credit_cents||0);if(balance<total){await c.query('ROLLBACK');return res.status(402).json({error:'Credito insufficiente.',balanceCents:balance,totalCostCents:total,shortageCents:total-balance,currency:settings.currency||'EUR'})}for(let i=0;i<units;i++)await c.query("INSERT INTO user_extra_entitlements(id,user_id,kind,board_id,units,source,amount_cents,expires_at) VALUES($1,$2,'jotter',NULL,1,'purchase',$3,now()+interval '30 days')",[crypto.randomUUID(),req.user.sub,unit]);await c.query('UPDATE users SET spot_credit_cents=spot_credit_cents-$1 WHERE id=$2',[total,req.user.sub]);await c.query("INSERT INTO pay_use_transactions(id,user_id,transaction_type,amount_cents,item_type,units,provider,external_id,description) VALUES($1,$2,'spend',$3,'jotter',$4,'internal-jotters',$5,$6)",[crypto.randomUUID(),req.user.sub,-total,units,requestId,`Acquisto ${units} Jotter extra; validità 30 giorni`]);await c.query('COMMIT');res.json({ok:true,units,totalCostCents:total,balanceCents:balance-total,expiresAt:new Date(Date.now()+30*86400000).toISOString(),currency:settings.currency||'EUR'})}catch(e){try{await c.query('ROLLBACK')}catch{};console.error('Acquisto Jotter:',e);res.status(500).json({error:'Acquisto non completato. Nessun credito è stato scalato.'})}finally{c.release()}});
app.get('/api/admin/users/:id/jotter-detail',auth,adminOnly,async(req,res)=>{const u=(await pool.query(`SELECT u.id,u.email,u.display_name,u.plan_code,u.subscription_current_period_end,p.name plan_name FROM users u LEFT JOIN billing_plans p ON p.id=u.plan_id WHERE u.id=$1`,[req.params.id])).rows[0];if(!u)return res.sendStatus(404);const boards=await pool.query(`SELECT b.id,b.title,b.room_code,b.created_at,je.expires_at jotter_expires_at,COALESCE(json_agg(json_build_object('id',pe.id,'units',pe.units,'pageFrom',pe.page_from,'pageTo',pe.page_to,'expiresAt',pe.expires_at)) FILTER(WHERE pe.id IS NOT NULL),'[]'::json) page_extras FROM boards b LEFT JOIN user_extra_entitlements je ON je.board_id=b.id AND je.kind='jotter' LEFT JOIN user_extra_entitlements pe ON pe.board_id=b.id AND pe.kind='page' WHERE b.owner_user_id=$1 GROUP BY b.id,je.expires_at ORDER BY b.created_at DESC`,[req.params.id]);res.json({user:{id:u.id,email:u.email,name:u.display_name,plan:u.plan_name||u.plan_code,nextRenewal:u.subscription_current_period_end},boards:boards.rows.map(b=>({id:b.id,title:b.title,roomCode:b.room_code,createdAt:b.created_at,jotterExpiresAt:b.jotter_expires_at,pageExtras:b.page_extras}))})});

